import{_ as d}from"./plugin-vue_export-helper-c27b6911.js";import{r as s,o as r,c as n,d as i,e as l,b as e,w as t,a as c,f as a}from"./app-31ccb12c.js";const u={},p=i("p",null,"前 30 题覆盖数字音频基础与常用算法，适合面试前快速自测。答案给的是骨架：结论、原理、取舍、工程例子。",-1),g=a('<h2 id="面试问答-上-基础与算法" tabindex="-1"><a class="header-anchor" href="#面试问答-上-基础与算法" aria-hidden="true">#</a> 面试问答（上）：基础与算法</h2><h3 id="_5-1-基础-q1—q12" tabindex="-1"><a class="header-anchor" href="#_5-1-基础-q1—q12" aria-hidden="true">#</a> 5.1 基础（Q1—Q12）</h3><p><strong>Q1 ★ 采样定理是什么？为什么常见 44.1k / 48k / 16k？</strong></p><ul><li><code>fs &gt; 2 f_max</code> 才能无混叠恢复；44.1k 覆盖 22.05k（人耳上限约 20k），来自 CD 时代的历史折中；48k 是专业/通信设备主流，且与 24/25/30/60 fps 视频帧率成整数关系；16k 是宽带语音标准（8k 带宽），覆盖语音清晰度所需频段。</li><li>关键是<strong>降采样前必须抗混叠</strong>，重建后必须模拟低通。</li></ul><p><strong>Q2 ★ 量化噪声与位深的关系？</strong></p><ul><li>满幅正弦：<code>SNR = 6.02N + 1.76 dB</code>；16 bit ≈ 98 dB，24 bit ≈ 146 dB。</li><li>实际受模拟前端限制：MEMS 麦 60—70 dB，codec 100 dB 左右。</li><li><code>ENOB = (SINAD - 1.76)/6.02</code>，用来判断「有效位数」。</li></ul><p><strong>Q3 dither 有什么用？设备端什么时候需要？</strong></p><ul><li>量化误差与信号相关会产生谐波失真；加约 1 LSB 的 TPDF 抖动把失真变成白噪声，听感更自然。</li><li>位深下变换（24→16）、低电平淡出时最有意义；设备端录音/播放通常不做，除非做母带或高动态范围处理。</li></ul><p><strong>Q4 ★ dBFS、dBV、dBu、dBSPL 的区别？0 dBFS 对应多少 SPL？</strong></p><ul><li>dBFS 是数字满刻度；dBV 参考 1 V，dBu 参考 0.775 V，dBSPL 参考 20 µPa。</li><li>换算链：麦克风灵敏度（如 -38 dBV/Pa）→ 94 dBSPL 对应 -38 dBV → 若 ADC 满刻度 1 Vrms，则 94 dBSPL 对应 -38 dBFS → 0 dBFS 约 132 dBSPL。</li><li>实际还要加 PGA 增益，且不同频率灵敏度不同（频响曲线）。</li></ul><p><strong>Q5 sample、frame、block 有什么区别？planar 和 interleaved 呢？</strong></p><ul><li>sample 是单声道单点；frame 是所有声道同一时刻的集合；block/period 是一批 frame。</li><li>interleaved 按帧交错存（LRLR），planar 按声道分开存（LLL、RRR）。</li><li>DMA/ALSA 多为 interleaved，算法库多用 planar；转换有开销，链路设计时尽量少转。</li></ul><p><strong>Q6 ★ S24_3LE、S24_LE、S32_LE 有什么区别？</strong></p><ul><li><code>S24_3LE</code>：24 bit 打包成 3 字节，无填充；USB/专业设备常见。</li><li><code>S24_LE</code>：24 bit 放在 32 bit 字的低 24 位，高 8 位填充；ALSA 内部常见。</li><li><code>S32_LE</code>：完整 32 bit 整数。</li><li>搞错会导致音量异常或噪声；还要注意左/右对齐和端序。</li></ul><p><strong>Q7 ★ MCLK、BCLK、LRCLK 的关系？I2S 时序关键点？</strong></p><ul><li><code>MCLK = 256/384/512 × fs</code>（codec 内部 ΣΔ 用）；<code>BCLK = fs × slot_bits × slots</code>；<code>LRCLK = fs</code>。</li><li>I2S：LRCLK 低=左声道、高=右声道；数据 MSB 在 LRCLK 跳变后延迟 1 个 BCLK；MSB-first。</li><li>主从必须明确，两边同时驱动 BCLK 会冲突。</li></ul><p><strong>Q8 I2S、TDM、PDM 怎么选？</strong></p><ul><li>I2S：2 声道、简单、codec/功放最常用。</li><li>TDM：多声道（4/8/16 slot），多麦阵列、车载；需要约定 slot 宽度和帧同步模式（DSP A/B）。</li><li>PDM：数字 MEMS 麦，1 bit 高采样率，需抽取滤波；布线简单但时钟易串扰。</li><li>SoundWire 用于手机/PC 多设备；USB Audio 用于外置声卡。</li></ul><p><strong>Q9 ★ 两个时钟域为什么会漂移？怎么解决？</strong></p><ul><li>晶振精度（±10—50 ppm）、温漂、PLL 抖动导致 fs 不完全相等。</li><li>50 ppm @48k ≈ 2.4 sample/s，10 分钟差约 30 ms。</li><li>解决：同源时钟、ASRC、反馈重采样（看 buffer 水位调速）、AEC 延迟跟踪。</li></ul><p><strong>Q10 ★ 端到端音频延迟由哪些部分组成？怎么测？</strong></p><ul><li>ADC 群延迟 + period/buffer + 用户态调度 + 算法 lookahead + 混音/SRC + DAC + 功放/声学。</li><li>测法：环回脉冲（播放→录音）、<code>latmus</code>、示波器看 BCLK 与模拟输出、人工嘴/人工耳。</li><li>先明确测的是「应用写入到出声」还是「声学入口到声学出口」。</li></ul><p><strong>Q11 ★ 什么是 xrun？怎么恢复和定位？</strong></p><ul><li>playback underrun：应用喂数据太慢，DMA 没数据；capture overrun：应用读太慢，缓冲被覆盖。ALSA 返回 <code>-EPIPE</code>。</li><li>恢复：<code>snd_pcm_prepare</code> 重新准备，或 <code>snd_pcm_recover</code>。</li><li>定位：<code>/proc/asound/.../status</code> 看 state/avail；<code>strace -T</code> 看 read/ioctl 耗时；<code>cyclictest</code>/<code>perf sched</code> 看调度延迟；检查 period 是否过小、是否有 page fault/malloc。</li></ul><p><strong>Q12 ★ 为什么语音前端常用 16 kHz？8k 和 48k 呢？</strong></p><ul><li>8k 采样只有 4k 带宽，丢失辅音高频，电话音质；16k 提供 8k 带宽，是宽带语音/Opus/ASR 的主流；48k 用于音乐、全带宽通话、AEC 高保真参考。</li><li>16k 的算力/模型输入更小，且与多数 ASR 前端匹配；需要音乐或超声场景才上 48k。</li></ul><h3 id="_5-2-算法-q13—q30" tabindex="-1"><a class="header-anchor" href="#_5-2-算法-q13—q30" aria-hidden="true">#</a> 5.2 算法（Q13—Q30）</h3><p><strong>Q13 ★ FIR 和 IIR 怎么选？</strong></p><ul><li>FIR：可线性相位、恒稳定，但阶数高、延迟大、算力大；适合线性相位 EQ、SRC、波束成形。</li><li>IIR：阶数低、算力小、延迟低，但相位非线性、需稳定性检查；适合实时 EQ、分频、去直流。</li><li>设备端语音链路通常 IIR 做基础滤波，FIR 做需要线性相位/精确频响的部分。</li></ul><p><strong>Q14 ★ 双二阶滤波器低频为什么容易出问题？怎么解决？</strong></p><ul><li><code>f0 &lt;&lt; fs</code> 时 <code>cos(w0) → 1</code>，极点紧贴单位圆且彼此靠近，float 系数量化误差被放大，导致频响偏移甚至不稳定。</li><li>对策：double 系数/状态、DF2T 结构、一阶节替代、coupled form、必要时改用状态空间/耦合形式，或换用双精度。</li></ul><p><strong>Q15 线性相位 FIR 的代价是什么？</strong></p><ul><li>群延迟 <code>(N-1)/2</code> 个采样，48k 下 1024 tap ≈ 10.7 ms；还有 pre-ringing，瞬态会被“抹开”。</li><li>对延迟敏感的通话/监听链路通常不用长线性相位 FIR。</li></ul><p><strong>Q16 ★ 采样率转换有哪些方法？怎么评价质量？</strong></p><ul><li>零阶保持/线性插值：便宜但混叠/镜像严重。</li><li>多相 FIR：主流，质量与抽头数相关。</li><li>窗函数 sinc：任意比率，质量好。</li><li>ASRC/Farrow：吸收时钟漂移。</li><li>指标：通带纹波、阻带衰减、THD+N、群延迟、CPU；库：libsamplerate、soxr、Speex、zita。</li></ul><p><strong>Q17 ★ 压缩器的参数怎么调？</strong></p><ul><li>Threshold 决定何时开始压；Ratio 决定压多少；Attack 太快会失真、太慢漏瞬态；Release 太短会抽吸。</li><li>语音常用：T = -18 ~ -12 dBFS，R=2:1—4:1，attack 5—20 ms，release 100—300 ms，软拐点。</li><li>立体声要联动，压缩后加 makeup，注意峰值不过 0 dBFS。</li></ul><p><strong>Q18 限幅器为什么需要 lookahead？</strong></p><ul><li>峰值是突发的，没有前瞻就只能等超了再降，已经削了；lookahead 提前看到峰值，用 ramp 平滑降增益。</li><li>代价是延迟（常见 1—5 ms）；真峰值检测还要 4× 过采样。</li></ul><p><strong>Q19 ★ AEC 的原理？NLMS 怎么更新？</strong></p><ul><li>模型：<code>d = s + h*x + v</code>；用自适应滤波器估计 <code>h</code>，重建回声并从麦克风信号减掉。</li><li>NLMS：<code>w += μ e x / (||x||² + δ)</code>，<code>e = d - w^T x</code>。</li><li>长尾用 PBFDAF（分块频域）降复杂度；滤波器长度覆盖 200—500 ms 混响。</li></ul><p><strong>Q20 ★ 双讲检测怎么做？为什么必须做？</strong></p><ul><li>近端说话时，自适应会把近端语音也“学”进回声路径，导致近端被抵消。</li><li>方法：Geigel（<code>|d| &gt; max|x| * th</code>）、归一化互相关、双滤波器（foreground/background）比较、相干性。</li><li>检测到双讲就冻结/放慢自适应，只保留 NLP 的保守抑制。</li></ul><p><strong>Q21 线性 AEC 之后为什么还需要 NLP？</strong></p><ul><li>扬声器、功放、ADC 的非线性，以及时钟漂移、路径变化，使线性滤波只能消 20—40 dB。</li><li>NLP/RES 用估计的回声能量做谱增益，进一步压残余；但要避免损伤近端语音（双讲时保守）。</li></ul><p><strong>Q22 ★ 谱减法为什么会产生 musical noise？怎么缓解？</strong></p><ul><li>噪声估计有方差，谱减后在随机频点留下孤立残留，听起来像“水声/鸟叫”。</li><li>缓解：过减因子 + 谱下限、时间/频率平滑、维纳/MMSE 软增益、噪声估计改进（MCRA）、深度学习方法。</li></ul><p><strong>Q23 维纳滤波和 MMSE-LSA 的区别？</strong></p><ul><li>维纳：<code>G = ξ/(1+ξ)</code>，基于均方误差，计算简单。</li><li>MMSE-LSA：最小化对数谱误差，<code>G = ξ/(1+ξ) exp(0.5 ∫_v^∞ e^-t/t dt)</code>，语音失真更小，但需要更准的先验 SNR。</li><li>工程上常用判决引导（decision-directed）估计先验 SNR，兼顾两者。</li></ul><p><strong>Q24 ★ 深度降噪和传统降噪相比，端侧部署要注意什么？</strong></p><ul><li>优势：对非平稳噪声、低 SNR 效果更好；可联合 AEC/去混响。</li><li>约束：MACs/参数量、内存带宽、定点/量化精度、流式因果性、帧长与延迟、模型更新与多平台移植。</li><li>常见做法：传统算法打底 + 轻量 DNN 做掩码/后处理，或 DSP 上跑小模型。</li></ul><p><strong>Q25 ★ delay-and-sum 和 MVDR 的区别？</strong></p><ul><li>DAS：按方向补偿时延后平均，鲁棒、无需统计信息，但旁瓣高、抑制有限。</li><li>MVDR：<code>w = R^-1 d/(d^H R^-1 d)</code>，在目标方向无失真约束下最小化输出功率，抑制强干扰更好；但需要准确的 <code>R</code> 和导向矢量，要对角加载。</li><li>工程上 GSC 更常用：固定波束 + 阻塞矩阵 + 自适应抵消。</li></ul><p><strong>Q26 DOA 怎么估计？GCC-PHAT 的原理？</strong></p><ul><li>两麦互谱做相位变换：<code>R12(τ)=IFFT(X1 X2*/|X1 X2*|)</code>，峰值对应 TDOA，再换算角度。</li><li>PHAT 加权抑制混响和幅度差异，低 SNR 下更鲁棒；多麦可用 SRP-PHAT 或 MUSIC。</li><li>注意空间混叠（间距 &gt; λ/2）和阵列校准。</li></ul><p><strong>Q27 ★ AGC 应该放在链路哪个位置？为什么？</strong></p><ul><li>一般在 NS 之后、编码/VAD 之前；放太前会把噪声一起放大，放太后可能让编码器过载。</li><li>不能和 codec 的模拟 AGC 重复；VAD 要在 AGC 前或做增益补偿，避免判决被增益影响。</li><li>目标电平：语音 -26 ~ -18 dBFS，通话约 -20 dBFS。</li></ul><p><strong>Q28 VAD 有哪些实现？hangover 的作用？</strong></p><ul><li>能量+过零率、谱特征、GMM（WebRTC VAD）、DNN。</li><li>hangover 在语音结束后保持 100—300 ms，防止尾音/弱音被切；太长会增加延迟和功耗。</li></ul><p><strong>Q29 ★ 语音前端链路的推荐顺序？为什么？</strong></p><ul><li><code>HPF → BF → AEC → NS → AGC → VAD</code>。</li><li>HPF 先去 DC/低频；BF 提升目标方向 SNR；AEC 必须在非线性 NS 之前，否则回声路径被破坏；AGC 在 NS 后避免放大噪声；VAD 最后做门控。</li><li>每级要能 bypass，方便定位问题。</li></ul><p><strong>Q30 去混响和丢包补偿分别怎么做？</strong></p><ul><li>去混响：WPE 用线性预测估计晚期混响并从当前帧减掉，多通道效果更好；也可用谱域/深度方法。</li><li>PLC：波形相似重复（WSOLA）、基音周期复制；Opus/LC3 内置 PLC；网络侧靠 jitter buffer + FEC。</li></ul><hr>',64),S=i("strong",null,"系列导航",-1),L=i("strong",null,"下一篇",-1);function A(C,B){const o=s("RouterLink");return r(),n("div",null,[i("blockquote",null,[i("p",null,[l("本文是「设备端音频与语音处理」系列第 5 篇（共 7 篇）。系列导览："),e(o,{to:"/source-study/audio/"},{default:t(()=>[l("从 pipeline 到 Linux 音频栈")]),_:1}),l("。")])]),p,c(" more "),g,i("p",null,[S,l("："),e(o,{to:"/source-study/audio/"},{default:t(()=>[l("系列导览")]),_:1}),l(" · "),L,l("："),e(o,{to:"/source-study/audio/06-interview-linux-tuning-scenarios.html"},{default:t(()=>[l("设备端音频（六）：面试问答 30 题（Linux、调优与场景）")]),_:1})])])}const _=d(u,[["render",A],["__file","05-interview-basics-algorithms.html.vue"]]);export{_ as default};
